package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.auth.model.entity.UserRole;
import dustin.cex.domains.monitoring.*;
import dustin.cex.domains.security.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;

/** 실제 판단 승인과 종결 실행의 서명을 구분하고 새 입금·의견·감사 실패·경합에서 원본 보존을 검증한다. */
class DepositMonitoringCaseDispositionIntegrationTest extends MonitoringCaseTestSupport {
    @Autowired DepositMonitoringCaseDispositions actions;
    @AfterEach void noFinancialEffects(){verifyNoInteractions(engine,producer,reader,price);assertEquals(0,count("user_balances"));assertEquals(0,jdbc.queryForObject("SELECT coalesce(sum(delta),0) FROM ledger_entries WHERE asset='BTC'",BigDecimal.class).signum());assertFalse(users.findById(customer.getId()).orElseThrow().isTradingRestricted());}
    DepositMonitoringCaseReviews.Review approved(DepositMonitoringCaseReviews.Finding finding)throws Exception{
        var scope=scope();viewEvidence(maker,scope);var r=reviews.propose(maker.user().getId(),maker.sid(),caseId,checker.user().getId(),UUID.randomUUID(),scope,new DepositMonitoringCaseReviews.Facts(finding,"사건 전체 자료를 확인한 내부 후속 판단"));
        decide(r,true,proof(r,true));reviews.inspect(maker.user().getId(),maker.sid(),r.payload().id());return r;
    }
    DepositMonitoringCaseDispositions.Request request(DepositMonitoringCaseReviews.Review r,DepositMonitoringCaseDispositions.Action action){return actions.propose(maker.user().getId(),maker.sid(),r.payload().id(),action,UUID.randomUUID());}
    DepositMonitoringCaseDispositions.Request closeRequest()throws Exception{return request(approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY),DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED);}
    OperatorMfaService.AuthorizationProof actionProof(DepositMonitoringCaseDispositions.Request r,boolean approve)throws Exception{var options=actions.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),approve).authentication();return new OperatorMfaService.AuthorizationProof(options.challengeId(),checker.key().assertion(options,"http://localhost:3003",true,counter.incrementAndGet(),null));}
    DepositMonitoringCaseDispositions.Request apply(DepositMonitoringCaseDispositions.Request r,boolean approve,OperatorMfaService.AuthorizationProof proof){return actions.decide(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),approve,proof);}
    String caseState(UUID id){return cases.members(maker.user().getId(),maker.sid(),id,null).investigation().status();}
    @Test void explicitSeparateSignatureClosesTheWholeCase()throws Exception{
        var r=closeRequest();assertEquals("OPEN",caseState(caseId));var proof=actionProof(r,true);
        mvc.perform(post("/api/admin/monitoring/case-actions/"+r.payload().id()+"/approve").header("Authorization","Bearer "+checker.access()).contentType("application/json").content(json.writeValueAsString(new DepositMonitoringCaseDispositionController.Decision(r.payloadHash(),proof)))).andExpect(status().isOk()).andExpect(header().string("Cache-Control",org.hamcrest.Matchers.containsString("no-store"))).andExpect(jsonPath("$.status").value("APPROVED"));
        assertEquals("CLOSED",caseState(caseId));assertEquals(1,count("deposit_monitoring_cases"));assertTrue(actions.referrals(maker.user().getId(),maker.sid(),0).isEmpty());
    }
    @Test void nextSignalCreatesANewCaseAndPreservesTheClosedHistory()throws Exception{var r=closeRequest();apply(r,true,actionProof(r,true));UUID closed=caseId;add();UUID current=jdbc.queryForObject("SELECT case_id FROM deposit_monitoring_case_heads WHERE user_id=?",UUID.class,customer.getId());assertNotEquals(closed,current);assertEquals("CLOSED",caseState(closed));assertEquals("OPEN",caseState(current));assertEquals(1,cases.members(maker.user().getId(),maker.sid(),closed,null).items().size());assertEquals(1,cases.members(maker.user().getId(),maker.sid(),current,null).items().size());assertEquals(2,count("deposit_monitoring_cases"));}
    @Test void reportingReferralIsDurableAndDoesNotCloseOrFile()throws Exception{var r=request(approved(DepositMonitoringCaseReviews.Finding.REFER_FOR_REPORTING_REVIEW),DepositMonitoringCaseDispositions.Action.REFER_FOR_REPORTING_REVIEW);apply(r,true,actionProof(r,true));assertEquals("OPEN",caseState(caseId));var list=actions.referrals(maker.user().getId(),maker.sid(),0);assertEquals(1,list.size());assertEquals(r.payload().id(),list.getFirst().requestId());assertEquals("AWAITING_REPORTING_REVIEW",list.getFirst().status());assertFalse(json.writeValueAsString(list).contains("rationale"));add();assertEquals(caseId,jdbc.queryForObject("SELECT case_id FROM deposit_monitoring_case_heads WHERE user_id=?",UUID.class,customer.getId()));}
    @Test void opinionApprovalAloneNeverExecutesTheAction()throws Exception{approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);assertEquals("OPEN",caseState(caseId));assertEquals(0,count("deposit_monitoring_case_actions"));assertEquals(0,count("deposit_monitoring_case_action_decisions"));}
    @Test void wrongFindingCannotBePromotedToClosureOrReferral()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.REQUIRES_FURTHER_REVIEW);for(var action:DepositMonitoringCaseDispositions.Action.values())rejects(409,()->request(r,action));assertEquals(0,count("deposit_monitoring_case_actions"));}
    @Test void explainedFindingCannotAuthorizeAReportingReferral()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);rejects(409,()->request(r,DepositMonitoringCaseDispositions.Action.REFER_FOR_REPORTING_REVIEW));}
    @Test void pendingOrRejectedJudgmentCannotExecute()throws Exception{var r=propose();rejects(409,()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));decide(r,false,proof(r,false));rejects(409,()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));}
    @Test void newSignalAfterJudgmentRequiresAWholeCaseReview()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);add();rejects(409,()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));assertEquals("OPEN",caseState(caseId));}
    @Test void newSignalAfterPreparingTheActionBlocksItsSignature()throws Exception{var r=closeRequest();var proof=actionProof(r,true);add();rejects(409,()->apply(r,true,proof));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));assertEquals("OPEN",caseState(caseId));}
    @Test void newOpinionAfterPreparingTheActionBlocksItsSignature()throws Exception{var r=closeRequest();var proof=actionProof(r,true);note(assessment,receipt.id(),"새로 받은 소명과 추가 확인 사항");rejects(409,()->apply(r,true,proof));assertEquals("OPEN",caseState(caseId));}
    @Test void laterOpinionReopensCurrentWorkWithoutErasingClosure()throws Exception{var r=closeRequest();apply(r,true,actionProof(r,true));assertEquals("CLOSED",caseState(caseId));note(assessment,receipt.id(),"종결 뒤 추가된 새로운 자료");assertEquals("OPEN",caseState(caseId));assertEquals(1,count("deposit_monitoring_case_action_decisions"));var next=closeRequest();apply(next,true,actionProof(next,true));assertEquals("CLOSED",caseState(caseId));assertEquals(2,count("deposit_monitoring_case_action_decisions"));}
    @Test void originalJudgmentSignatureCannotExecuteAnAction()throws Exception{var review=propose();var old=proof(review,true);decide(review,true,old);reviews.inspect(maker.user().getId(),maker.sid(),review.payload().id());var r=request(review,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED);rejects(403,()->apply(r,true,old));assertEquals("OPEN",caseState(caseId));}
    @Test void actionSignatureCannotChangeDecisionDirection()throws Exception{var r=closeRequest();var proof=actionProof(r,true);rejects(403,()->apply(r,false,proof));assertEquals("APPROVED",apply(r,true,proof).status());}
    @Test void rejectionDoesNotCloseAndAllowsANewAction()throws Exception{var r=closeRequest();assertEquals("REJECTED",apply(r,false,actionProof(r,false)).status());assertEquals("OPEN",caseState(caseId));var next=actions.propose(maker.user().getId(),maker.sid(),r.payload().reviewId(),r.payload().action(),UUID.randomUUID());assertEquals("APPROVED",apply(next,true,actionProof(next,true)).status());assertEquals("CLOSED",caseState(caseId));}
    @Test void sameKeyHasOneImmutableIntent()throws Exception{var review=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);UUID key=UUID.randomUUID();var r=actions.propose(maker.user().getId(),maker.sid(),review.payload().id(),DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED,key);assertEquals(r,actions.propose(maker.user().getId(),maker.sid(),review.payload().id(),r.payload().action(),key));assertEquals(1,count("deposit_monitoring_case_actions"));}
    @Test void consumedActionSignatureCannotBeReplayed()throws Exception{var r=closeRequest();var proof=actionProof(r,true);apply(r,true,proof);rejects(409,()->apply(r,true,proof));assertEquals(1,count("deposit_monitoring_case_action_decisions"));}
    @Test void wrongPayloadHashCannotConsumeTheSignature()throws Exception{var r=closeRequest();var proof=actionProof(r,true);rejects(409,()->actions.decide(checker.user().getId(),checker.sid(),r.payload().id(),"0".repeat(64),true,proof));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));}
    @Test void expiryIsCheckedWithoutChangingTheIntent()throws Exception{var r=closeRequest();time.set(r.payload().expiresAt());rejects(409,()->actions.options(checker.user().getId(),checker.sid(),r.payload().id(),r.payloadHash(),true));assertEquals(0,count("deposit_monitoring_case_action_decisions"));}
    @Test void revokedMakerCannotBeUsedForExecution()throws Exception{var r=closeRequest();var proof=actionProof(r,true);jdbc.update("UPDATE users SET enabled=false WHERE id=?",maker.user().getId());rejects(403,()->apply(r,true,proof));}
    @Test void anotherApproverCannotExecuteTheAction()throws Exception{var r=closeRequest();var other=account(UserRole.APPROVER);rejects(404,()->actions.options(other.user().getId(),other.sid(),r.payload().id(),r.payloadHash(),true));}
    @Test void anotherOperatorCannotProposeFromThePrivateJudgment()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);var other=account(UserRole.OPERATOR);rejects(404,()->actions.propose(other.user().getId(),other.sid(),r.payload().id(),DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED,UUID.randomUUID()));}
    @Test void missingCurrentReasonViewPreventsTheIntent()throws Exception{var r=propose();decide(r,true,proof(r,true));rejects(409,()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));}
    @Test void proposalAuditFailureLeavesNoIntentOrBinding()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);doThrow(new IllegalStateException("격리 실행 요청 감사 실패")).when(audit).record(anyLong(),eq("MONITORING_CASE_ACTION_PROPOSED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));assertEquals(0,count("deposit_monitoring_case_actions"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM operator_approval_bindings WHERE kind='TM_CASE_ACTION'",Long.class));}
    @Test void omittedProposalAuditCannotCommit()throws Exception{var r=approved(DepositMonitoringCaseReviews.Finding.EXPLAINED_ACTIVITY);doNothing().when(audit).record(anyLong(),eq("MONITORING_CASE_ACTION_PROPOSED"),anyString(),anyString(),anyString());cause("사건 후속 업무에는 실행 내용의 필수 감사가 필요합니다",()->request(r,DepositMonitoringCaseDispositions.Action.CLOSE_EXPLAINED));assertEquals(0,count("deposit_monitoring_case_actions"));}
    @Test void executionAuditFailurePreservesOpenCaseAndUnconsumedProof()throws Exception{var r=closeRequest();var proof=actionProof(r,true);doThrow(new IllegalStateException("격리 종결 감사 실패")).when(audit).record(anyLong(),eq("MONITORING_CASE_ACTION_DECIDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->apply(r,true,proof));assertEquals("OPEN",caseState(caseId));assertEquals(0,count("deposit_monitoring_case_action_decisions"));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));}
    @Test void omittedExecutionAuditCannotCommit()throws Exception{var r=closeRequest();var proof=actionProof(r,true);doNothing().when(audit).record(anyLong(),eq("MONITORING_CASE_ACTION_DECIDED"),anyString(),anyString(),anyString());cause("사건 후속 업무에는 실행 내용의 필수 감사가 필요합니다",()->apply(r,true,proof));assertEquals("OPEN",caseState(caseId));assertFalse(jdbc.queryForObject("SELECT consumed FROM operator_authorization_challenges WHERE id=?",Boolean.class,proof.challengeId()));}
    @Test void historiesAndCurrentHeadCannotBeArbitrarilyRewritten()throws Exception{var r=closeRequest();apply(r,true,actionProof(r,true));for(String table:List.of("deposit_monitoring_case_actions","deposit_monitoring_case_action_decisions")){assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("DELETE FROM "+table));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("TRUNCATE "+table+" CASCADE"));}assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("UPDATE deposit_monitoring_case_heads SET case_id=case_id"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute("DELETE FROM deposit_monitoring_case_heads"));assertEquals("CLOSED",caseState(caseId));}
    @Test void customersAndAuditorsCannotPerformCaseActions()throws Exception{var r=closeRequest();var auditor=account(UserRole.AUDITOR);for(String token:List.of(customerAccess,auditor.access()))mvc.perform(post("/api/admin/monitoring/case-actions/"+r.payload().id()+"/approve/options").header("Authorization","Bearer "+token).contentType("application/json").content(json.writeValueAsString(new DepositMonitoringCaseDispositionController.Confirmation(r.payloadHash())))).andExpect(status().isForbidden());mvc.perform(get("/api/admin/monitoring/case-actions/report-referrals").header("Authorization","Bearer "+customerAccess)).andExpect(status().isForbidden());}
    @Test void referralReadsRequireFreshAuthenticationAndMandatoryAudit()throws Exception{var auditor=account(UserRole.AUDITOR);assertTrue(actions.referrals(auditor.user().getId(),auditor.sid(),0).isEmpty());jdbc.update("UPDATE refresh_tokens SET mfa_verified_at=mfa_verified_at-interval '6 minutes' WHERE session_id=?",auditor.sid());rejects(403,()->actions.referrals(auditor.user().getId(),auditor.sid(),0));doThrow(new IllegalStateException("격리 회부 조회 감사 실패")).when(audit).record(anyLong(),eq("MONITORING_REPORT_REFERRALS_READ"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->actions.referrals(maker.user().getId(),maker.sid(),0));}
    @Test void parallelReuseOfOneExecutionProofHasOneWinner()throws Exception{var r=closeRequest();var proof=actionProof(r,true);var start=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){java.util.concurrent.Callable<String> call=()->{assertTrue(start.await(5,java.util.concurrent.TimeUnit.SECONDS));try{return apply(r,true,proof).status();}catch(org.springframework.web.server.ResponseStatusException ex){return Integer.toString(ex.getStatusCode().value());}};var a=pool.submit(call);var b=pool.submit(call);start.countDown();assertEquals(Set.of("APPROVED","409"),Set.of(a.get(10,java.util.concurrent.TimeUnit.SECONDS),b.get(10,java.util.concurrent.TimeUnit.SECONDS)));}assertEquals(1,count("deposit_monitoring_case_action_decisions"));}
    @Test void twoPendingIntentsCannotBothExecute()throws Exception{var first=closeRequest();var second=actions.propose(maker.user().getId(),maker.sid(),first.payload().reviewId(),first.payload().action(),UUID.randomUUID());var firstProof=actionProof(first,true);apply(first,true,firstProof);rejects(409,()->actions.options(checker.user().getId(),checker.sid(),second.payload().id(),second.payloadHash(),true));assertEquals(1,count("deposit_monitoring_case_action_decisions"));}
    @Test void ambientTransactionsAndUnsupportedRoutesAreRejected()throws Exception{assertThrows(IllegalStateException.class,()->new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->actions.referrals(maker.user().getId(),maker.sid(),0)));mvc.perform(get("/api/admin/monitoring/case-actions").header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());}
}
